package cn.course.community;
import java.util.*;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:members;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","app.seed=true","app.seed-password=TestOnly!2026Long"})
@AutoConfigureMockMvc @Transactional
class MemberManagementTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired Store s;@Autowired MemberManagement members;@Autowired CommunityService domain;
 long uid(String who){return s.uid(who+"@example.test");}int rev(){return s.db.queryForObject("SELECT roster_revision FROM course WHERE id=1",Integer.class);}long events(){return s.db.queryForObject("SELECT COUNT(*) FROM course_member_change",Long.class);}long notes(){return s.db.queryForObject("SELECT COUNT(*) FROM notification",Long.class);}
 void checkPost(String path,Object body,int code)throws Exception{mvc.perform(post(path).with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(body))).andExpect(status().is(code));}
 @Test void teacherRosterShowsSafeContactFieldsAndCounts()throws Exception{String body=mvc.perform(get("/api/courses/1/members").with(user("teacher@example.test"))).andExpect(status().isOk()).andExpect(jsonPath("total").value(3)).andExpect(jsonPath("pageSize").value(20)).andReturn().getResponse().getContentAsString();assertFalse(body.contains("password"));assertFalse(body.contains("draft_json"));assertTrue(body.contains("student@example.test"));}
 @Test void studentsAssistantsAndOtherCoursesCannotReadRosterOrHistory()throws Exception{s.db.update("UPDATE course_member SET role='ASSISTANT' WHERE course_id=1 AND user_id=?",uid("peer"));for(String who:List.of("student","peer","outsider"))for(String suffix:List.of("","/history"))mvc.perform(get("/api/courses/1/members"+suffix).with(user(who+"@example.test"))).andExpect(status().isForbidden());}
 @Test void addExistingAccountCaseInsensitivelyWithoutChangingOtherMembership(){long users=s.db.queryForObject("SELECT COUNT(*) FROM app_user",Long.class);members.add(1," OUTSIDER@example.test ","STUDENT",uid("teacher"),rev(),"加入课程");assertEquals("STUDENT",s.role(1,uid("outsider")));assertEquals("STUDENT",s.role(2,uid("outsider")));assertEquals(users,s.db.queryForObject("SELECT COUNT(*) FROM app_user",Long.class));}
 @Test void unknownAccountNotCreated()throws Exception{long before=events(),n=notes();checkPost("/api/courses/1/members",Map.of("email","new@example.test","role","STUDENT","revision",rev()),422);assertEquals(before,events());assertEquals(n,notes());assertEquals(0,s.db.queryForObject("SELECT COUNT(*) FROM app_user WHERE email='new@example.test'",Integer.class));}
 @Test void duplicateAddDoesNotMutate()throws Exception{int r=rev();long n=notes();checkPost("/api/courses/1/members",Map.of("email","student@example.test","role","ASSISTANT","revision",r),409);assertEquals(r,rev());assertEquals(n,notes());assertEquals("STUDENT",s.role(1,uid("student")));}
 @Test void staleMutationsPreserveNewerRoster()throws Exception{int r=rev();members.change(1,uid("student"),uid("teacher"),new MemberManagement.Change("ASSISTANT","协助课程",r));long before=events();checkPost("/api/courses/1/members/"+uid("peer")+"/remove",new MemberManagement.Remove("旧窗口",r),409);checkPost("/api/courses/1/members",Map.of("email","outsider@example.test","role","STUDENT","revision",r),409);assertEquals(before,events());}
 @Test void teacherAndSelfProtection()throws Exception{long second=s.insert("INSERT INTO app_user(email,display_name,password_hash) SELECT 'teacher2@example.test','第二位教师',password_hash FROM app_user WHERE id=?",uid("teacher"));s.db.update("INSERT INTO course_member(course_id,user_id,role) VALUES(1,?,'TEACHER')",second);for(long id:List.of(uid("teacher"),second)){checkPost("/api/courses/1/members/"+id+"/role",new MemberManagement.Change("STUDENT","不得降权教师",rev()),422);checkPost("/api/courses/1/members/"+id+"/remove",new MemberManagement.Remove("不得移出教师",rev()),422);}assertEquals("TEACHER",s.role(1,second));}
 @Test void noTeacherPromotionOrNullRole()throws Exception{for(Object role:List.of("TEACHER","ADMIN")){checkPost("/api/courses/1/members",Map.of("email","outsider@example.test","role",role),400);checkPost("/api/courses/1/members/"+uid("student")+"/role",Map.of("role",role,"reason","非法提升","revision",rev()),400);}checkPost("/api/courses/1/members",Map.of("email","outsider@example.test"),400);}
 @Test void writesRequireTeacherSessionCsrfAndReason()throws Exception{String path="/api/courses/1/members/"+uid("peer")+"/remove";String body=json.writeValueAsString(new MemberManagement.Remove("退出课程",rev()));mvc.perform(post(path).with(user("teacher@example.test")).contentType("application/json").content(body)).andExpect(status().isForbidden());mvc.perform(get("/api/courses/1/members")).andExpect(status().isUnauthorized());for(String who:List.of("student","outsider"))mvc.perform(post(path).with(user(who+"@example.test")).with(csrf()).contentType("application/json").content(body)).andExpect(status().isForbidden());checkPost(path,Map.of("reason"," ","revision",rev()),400);checkPost(path,Map.of("reason","缺少名单版本"),400);checkPost("/api/courses/1/members/"+uid("peer")+"/role",Map.of("role","ASSISTANT","reason","缺少名单版本"),400);}
 @Test void promotingStudentToAssistantStopsStudentWrites()throws Exception{members.change(1,uid("student"),uid("teacher"),new MemberManagement.Change("ASSISTANT","课程辅助",rev()));mvc.perform(post("/api/assignments/1/entries").with(user("student@example.test")).with(csrf())).andExpect(status().isForbidden());var e=domain.getEntry(1,uid("student"));mvc.perform(put("/api/entries/1/draft").with(user("student@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(new ApiController.DraftRequest("不应保存",(JsonNode)e.get("content"),((Number)e.get("revision")).intValue(),List.of())))).andExpect(status().isForbidden());mvc.perform(post("/api/entries/1/submissions").with(user("student@example.test")).with(csrf()).header("Idempotency-Key","assistant-no-submit").contentType("application/json").content("{\"revision\":1}")).andExpect(status().isForbidden());mvc.perform(get("/api/courses/1/review-queue").with(user("student@example.test"))).andExpect(status().isOk());}
 @Test void assistantCannotManageMembersOrPublishScores()throws Exception{members.change(1,uid("peer"),uid("teacher"),new MemberManagement.Change("ASSISTANT","助教",rev()));mvc.perform(post("/api/courses/1/members/"+uid("student")+"/remove").with(user("peer@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(new MemberManagement.Remove("非法操作",rev())))).andExpect(status().isForbidden());mvc.perform(get("/api/submissions/2/review-draft").with(user("peer@example.test"))).andExpect(status().isForbidden());}
 @Test void assistantCannotUploadToFormerStudentEntry()throws Exception{members.change(1,uid("student"),uid("teacher"),new MemberManagement.Change("ASSISTANT","协助",rev()));mvc.perform(multipart("/api/entries/1/media").file(new org.springframework.mock.web.MockMultipartFile("file","test.png","image/png",new byte[]{1,2})).with(user("student@example.test")).with(csrf())).andExpect(status().isForbidden());}
 @Test void removedMemberCannotReadOwnPriorMedia()throws Exception{String id=java.util.UUID.randomUUID().toString();s.db.update("INSERT INTO entry_media(id,entry_id,mime_type,width,height,body,created_at) VALUES(?,1,'image/png',1,1,?,?)",id,new byte[]{1,2},Store.now());members.remove(1,uid("student"),uid("teacher"),new MemberManagement.Remove("移出",rev()));mvc.perform(get("/api/media/"+id).with(user("student@example.test"))).andExpect(status().isForbidden());assertEquals(1,s.db.queryForObject("SELECT COUNT(*) FROM entry_media WHERE id=?",Integer.class,id));}
 @Test void changingBackToStudentRetainsPriorWork(){members.change(1,uid("peer"),uid("teacher"),new MemberManagement.Change("ASSISTANT","协助",rev()));members.change(1,uid("peer"),uid("teacher"),new MemberManagement.Change("STUDENT","继续作答",rev()));var e=domain.getEntry(2,uid("peer"));domain.save(2,new ApiController.DraftRequest("恢复学生作答",(JsonNode)e.get("content"),((Number)e.get("revision")).intValue(),List.of()),uid("peer"));assertEquals("恢复学生作答",domain.getEntry(2,uid("peer")).get("title"));}
 @Test void removalPreservesArtifactsButDeniesCourseAccess()throws Exception{long entries=s.db.queryForObject("SELECT COUNT(*) FROM entry",Long.class),versions=s.db.queryForObject("SELECT COUNT(*) FROM submission",Long.class),grades=s.db.queryForObject("SELECT COUNT(*) FROM evaluation",Long.class);members.remove(1,uid("student"),uid("teacher"),new MemberManagement.Remove("移出但保留历史",rev()));assertEquals(entries,s.db.queryForObject("SELECT COUNT(*) FROM entry",Long.class));assertEquals(versions,s.db.queryForObject("SELECT COUNT(*) FROM submission",Long.class));assertEquals(grades,s.db.queryForObject("SELECT COUNT(*) FROM evaluation",Long.class));for(String path:List.of("/api/entries/1","/api/submissions/1","/api/courses/1/assignments","/api/courses/1/progress","/api/courses/1/evidence"))mvc.perform(get(path).with(user("student@example.test"))).andExpect(status().isForbidden());mvc.perform(get("/api/courses").with(user("student@example.test"))).andExpect(jsonPath("length()").value(0));mvc.perform(get("/api/auth/me").with(user("student@example.test"))).andExpect(status().isOk());}
 @Test void removalHidesOldNotificationsAndReaddRestoresOwnHistory()throws Exception{members.remove(1,uid("student"),uid("teacher"),new MemberManagement.Remove("离开",rev()));mvc.perform(get("/api/notifications").with(user("student@example.test"))).andExpect(jsonPath("items.length()").value(0));members.add(1,"student@example.test","STUDENT",uid("teacher"),rev(),"重新加入，恢复历史访问");mvc.perform(get("/api/entries/1").with(user("student@example.test"))).andExpect(status().isOk());assertEquals(1,s.db.queryForObject("SELECT COUNT(*) FROM entry WHERE assignment_id=1 AND author_id=?",Integer.class,uid("student")));}
 @Test void noOpRoleAndRepeatedRemovalDoNotCreateExtraEvents()throws Exception{long n=events();checkPost("/api/courses/1/members/"+uid("student")+"/role",new MemberManagement.Change("STUDENT","未变化",rev()),422);assertEquals(n,events());members.remove(1,uid("peer"),uid("teacher"),new MemberManagement.Remove("离开",rev()));n=events();checkPost("/api/courses/1/members/"+uid("peer")+"/remove",new MemberManagement.Remove("重复",rev()),404);assertEquals(n,events());}
 @Test void serverPaginationFiltersAndLiteralWildcardSearch()throws Exception{for(int i=0;i<25;i++){long id=s.insert("INSERT INTO app_user(email,display_name,password_hash) SELECT ?,?,password_hash FROM app_user WHERE id=?","page"+i+"@example.test","测试成员"+i,uid("teacher"));s.db.update("INSERT INTO course_member(course_id,user_id,role) VALUES(1,?,'STUDENT')",id);}mvc.perform(get("/api/courses/1/members").with(user("teacher@example.test"))).andExpect(jsonPath("members.length()").value(20)).andExpect(jsonPath("total").value(28));mvc.perform(get("/api/courses/1/members?page=2&role=STUDENT").with(user("teacher@example.test"))).andExpect(jsonPath("members.length()").value(7)).andExpect(jsonPath("total").value(27));mvc.perform(get("/api/courses/1/members").param("q","%").with(user("teacher@example.test"))).andExpect(jsonPath("total").value(0));mvc.perform(get("/api/courses/1/members?q=PAGE24").with(user("teacher@example.test"))).andExpect(jsonPath("total").value(1));for(String query:List.of("page=0","page=-1","role=ADMIN","page=xyz"))mvc.perform(get("/api/courses/1/members?"+query).with(user("teacher@example.test"))).andExpect(status().isBadRequest());}
 @Test void historyContainsActorReasonAndBeforeAfterRolesNotCredentials(){members.change(1,uid("peer"),uid("teacher"),new MemberManagement.Change("ASSISTANT","课程辅助岗位调整",rev()));var h=members.history(1,uid("teacher")).getFirst();assertEquals("ROLE",h.get("action_type"));assertEquals("STUDENT",h.get("before_role"));assertEquals("ASSISTANT",h.get("after_role"));assertEquals("课程辅助岗位调整",h.get("reason"));assertFalse(h.toString().contains("password_hash"));assertFalse(h.toString().contains("draft_json"));}
 @Test void changeNotificationDoesNotCopyReasonOrSendRemovalToIneligibleUser(){members.change(1,uid("peer"),uid("teacher"),new MemberManagement.Change("ASSISTANT","PRIVATE-REASON",rev()));var n=s.one("SELECT * FROM notification ORDER BY id DESC LIMIT 1");assertEquals(uid("peer"),s.id(n,"recipient_id"));assertEquals("course",n.get("target_type"));assertFalse(n.toString().contains("PRIVATE-REASON"));long total=notes();members.remove(1,uid("peer"),uid("teacher"),new MemberManagement.Remove("退出",rev()));assertEquals(total,notes());}
}
